-- Photo-matched school / church massing on the exact county footprint
-- (spec.poly in InstitutionReconstruction.lua, footprint + photo anchors in
-- InstitutionFootprints.lua generated by tools/reconstruction/
-- institution_footprints.py).
--
-- spec.poly fields (lengths in true metres; colours 0xRRGGBB):
--   floors, storey, h (wall height, default floors*storey + parapet), parapet
--   datum = anchor key whose ground sets the floor level (default mean ground)
--   plinth = {h, color, material}            base course / rusticated storey
--   bands  = {{at, h, color, material}}       stringcourses
--   cornice = {h, out, color, material}       top cornice or coping
--   roofColor
--   win = {n, w, h, gap, bay, sill, frame, glass, from (first floor, 1-based),
--          style = "punched" | "ribbon"}
--   groundWin = {...}                         a different ground-floor window
--   blank = {anchor keys}                     walls those photos show windowless
--   entrances = {{at, w, h, style ("arch"|"flat"), color, surround, steps,
--                 canopy = {d, color}, columns}}
--   signs = {{at, kind ("wall"|"monument"|"board"|"pylon"|"banner"), lines =
--             {{text, size, font, color}}, w, h, y, out, bg, post}}
-- An anchor key "<pano 8>_<heading>" is the wall point where that reference
-- photo's centre ray meets the footprint; freestanding signs stand `out`
-- metres from it toward the camera.
local Poly = {}

local function hex(v)
	return Color3.fromRGB(math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256)
end
local function mat(name, fallback)
	if not name then return fallback end
	local ok, m = pcall(function() return Enum.Material[name] end)
	return ok and m or fallback
end
local FONTS = { serif = Enum.Font.Garamond, sans = Enum.Font.GothamBold, slab = Enum.Font.Bodoni,
	plain = Enum.Font.Gotham, script = Enum.Font.Fondamento, block = Enum.Font.SourceSansBold }

function Poly.Build(b, spec, ctx, Shapes, fp)
	local P = spec.poly
	local S = ctx.S
	local function H(m) return m * S end
	local function L(m) return m * S * 1.3 end
	-- identity frame: u = source x, v = source z
	local F = Shapes.frame(ctx, { 0, 0 }, 90)
	local ring = fp.poly
	local lo, mean = Shapes.groundOf(F, ring)
	local ground = mean
	if P.datum and fp.hits[P.datum] then
		local h = fp.hits[P.datum]
		ground = F.ground(h[1], h[2]) or mean
	end
	local storey = P.storey or 3.8
	local wallH = P.h or ((P.floors or 2) * storey + (P.parapet or 1.0))
	local top = ground + H(wallH)
	local wall = spec.wall and hex(spec.wall) or ctx.wall
	local material = mat(spec.material, ctx.material)
	local corn = P.cornice

	-- height zones: P.parts = {{at, depth, width, floors | h}} carves a lower
	-- (or taller) block out of the footprint at a photo anchor - a rectangle
	-- `width` along that wall and `depth` into the building. The rest of the
	-- footprint is split into convex-clipped pieces around it.
	local function clip(poly, nx, nz, c)
		-- keep points with nx*x + nz*z <= c (Sutherland-Hodgman, one plane)
		local out = {}
		local n = #poly
		for i = 1, n do
			local a, bq = poly[i], poly[i % n + 1]
			local da = nx * a[1] + nz * a[2] - c
			local db = nx * bq[1] + nz * bq[2] - c
			if da <= 0 then table.insert(out, a) end
			if (da < 0 and db > 0) or (da > 0 and db < 0) then
				local t = da / (da - db)
				table.insert(out, { a[1] + (bq[1] - a[1]) * t, a[2] + (bq[2] - a[2]) * t })
			end
		end
		return out
	end
	local function area(poly)
		local A = 0
		for i = 1, #poly do
			local a, c = poly[i], poly[i % #poly + 1]
			A += a[1] * c[2] - c[1] * a[2]
		end
		return math.abs(A) / 2
	end
	local pieces = { { poly = ring, floors = P.floors or 2, h = wallH } }
	for _, part in ipairs(P.parts or {}) do
		local hit = fp.hits[part.at]
		if hit then
			-- wall direction at the anchor from the nearest ring edge
			local best, bd, tx, tz
			for i = 1, #ring do
				local a, c = ring[i], ring[i % #ring + 1]
				local dx, dz = c[1] - a[1], c[2] - a[2]
				local len2 = dx * dx + dz * dz
				local t = math.clamp(((hit[1] - a[1]) * dx + (hit[2] - a[2]) * dz) / len2, 0, 1)
				local qx, qz = a[1] + dx * t - hit[1], a[2] + dz * t - hit[2]
				local d = qx * qx + qz * qz
				if not bd or d < bd then best, bd, tx, tz = i, d, dx / math.sqrt(len2), dz / math.sqrt(len2) end
			end
			-- inward normal: toward the footprint centroid
			local cxm, czm = 0, 0
			for _, p in ipairs(ring) do cxm += p[1]; czm += p[2] end
			cxm, czm = cxm / #ring, czm / #ring
			local nx, nz = -tz, tx
			if (cxm - hit[1]) * nx + (czm - hit[2]) * nz < 0 then nx, nz = -nx, -nz end
			local depth = part.depth * 1.3
			local half = (part.width or 1000) * 1.3 / 2
			local hd = nx * hit[1] + nz * hit[2]
			local hs = tx * hit[1] + tz * hit[2]
			local floorsP = part.floors or 1
			local hP = part.h or (floorsP * storey + (part.parapet or P.parapet or 1.0))
			local nextPieces = {}
			for _, pc in ipairs(pieces) do
				local inner = clip(clip(clip(pc.poly, nx, nz, hd + depth), tx, tz, hs + half), -tx, -tz, -(hs - half))
				local far = clip(pc.poly, -nx, -nz, -(hd + depth))
				local near = clip(pc.poly, nx, nz, hd + depth)
				local left = clip(near, -tx, -tz, -(hs + half))
				local right = clip(near, tx, tz, hs - half)
				for _, q in ipairs({ { far, pc.floors, pc.h }, { left, pc.floors, pc.h }, { right, pc.floors, pc.h }, { inner, floorsP, hP } }) do
					if #q[1] >= 3 and area(q[1]) > 4 then
						table.insert(nextPieces, { poly = q[1], floors = q[2], h = q[3] })
					end
				end
			end
			pieces = nextPieces
		end
	end
	local edges = {}
	for _, pc in ipairs(pieces) do
		local pTop = ground + H(pc.h)
		local es = Shapes.extrude(b, F, pc.poly, {
			name = "Walls", base = lo - 1.5, top = pTop, material = material, color = wall, t = 2,
			coping = corn and { h = H(corn.h or 0.6), out = L(corn.out or 0.25), color = corn.color and hex(corn.color) or wall,
				material = mat(corn.material, Enum.Material.SmoothPlastic) } or nil,
			roof = { color = P.roofColor and hex(P.roofColor) or Color3.fromRGB(120, 118, 114) },
		})
		for _, e in ipairs(es) do
			e.floors = pc.floors
			table.insert(edges, e)
		end
	end
	local function anchor(key)
		local h = fp.hits[key]
		if not h then return nil end
		local e, x = Shapes.edgeAt(F, edges, h[1], h[2])
		return e, x, h
	end

	-- base course / rusticated storey and stringcourses
	local function band(y0, y1, color, material2, proud)
		for _, e in ipairs(edges) do
			if y1 < e.top - 0.5 then
				b:part("Band", Vector3.new(e.len + 2 * proud, y1 - y0, 2 * proud + 0.2),
					e.face * CFrame.new(0, (y0 + y1) / 2, -proud + 0.1), material2, color)
			end
		end
	end
	if P.plinth then
		band(lo - 1.5, ground + H(P.plinth.h or 1), P.plinth.color and hex(P.plinth.color) or wall,
			mat(P.plinth.material, material), 0.35)
	end
	for _, s in ipairs(P.bands or {}) do
		band(ground + H(s.at), ground + H(s.at + (s.h or 0.3)), s.color and hex(s.color) or wall, mat(s.material, Enum.Material.Concrete), 0.3)
	end

	-- windows
	local blank = {}
	for _, key in ipairs(P.blank or {}) do
		local e = anchor(key)
		if e then blank[e] = true end
	end
	local doorsAt = {}
	for _, en in ipairs(P.entrances or {}) do
		local e, x = anchor(en.at)
		if e then
			doorsAt[e] = doorsAt[e] or {}
			table.insert(doorsAt[e], { x - L(en.dx or 0), L((en.w or 2.4) / 2 + 1.5) })
		end
	end
	local glassDefault = Color3.fromRGB(46, 54, 62)
	local function windows(w, floorsFrom, floorsMax)
		if not w then return end
		local frame = w.frame and hex(w.frame) or nil
		local glass = w.glass and hex(w.glass) or glassDefault
		for _, e in ipairs(edges) do
			local floorsTo = math.min(floorsMax, e.floors)
			if not blank[e] and floorsTo >= floorsFrom and e.len > L(w.bay or 4) + L(2) then
				local g0 = ground + H((floorsFrom - 1) * storey)
				if w.style == "ribbon" then
					for k = floorsFrom, floorsTo do
						local y0 = ground + H((k - 1) * storey + (w.sill or 1.0))
						local hh = H(w.h or 1.8)
						local span = e.len - L(w.margin or 1.5) * 2
						if frame then
							b:part("RibbonFrame", Vector3.new(span + 0.6, hh + 0.6, 0.25), e.face * CFrame.new(0, y0 + hh / 2, -0.1), Enum.Material.Metal, frame)
						end
						b:part("RibbonGlass", Vector3.new(span, hh, 0.3), e.face * CFrame.new(0, y0 + hh / 2, -0.2), Enum.Material.Glass, glass)
						local mull = math.floor(span / L(w.mullion or 1.6))
						for m = 1, mull - 1 do
							b:part("RibbonMullion", Vector3.new(0.3, hh, 0.45), e.face * CFrame.new(-span / 2 + m * span / mull, y0 + hh / 2, -0.3),
								Enum.Material.Metal, frame or Color3.fromRGB(80, 84, 88))
						end
						if w.transom then
							b:part("RibbonTransom", Vector3.new(span, 0.3, 0.45), e.face * CFrame.new(0, y0 + hh * w.transom, -0.3), Enum.Material.Metal, frame or Color3.fromRGB(80, 84, 88))
						end
					end
				else
					Shapes.punched(b, e, {
						ground = g0, floors = floorsTo - floorsFrom + 1, storey = H(storey), sill = H(w.sill or 0.9), h = H(w.h or 1.8),
						w = L(w.w or 1.0), n = w.n or 1, gap = L(w.gap or 0.25), bay = L(w.bay or 3.6), margin = L(w.margin or 1.8),
						glass = frame or glass, wall = frame or wall, wallMat = frame and Enum.Material.SmoothPlastic or material,
						spandrelColor = wall, spandrelMat = material, stone = w.sillColor and hex(w.sillColor) or nil,
						skip = doorsAt[e], pane = frame and glass or nil,
					})
				end
			end
		end
	end
	local floors = 99
	if P.groundWin then
		windows(P.groundWin, 1, 1)
		windows(P.win, 2, floors)
	else
		windows(P.win, (P.win and P.win.from) or 1, floors)
	end

	-- entrances
	for _, en in ipairs(P.entrances or {}) do
		local e, x = anchor(en.at)
		if e then
			-- dx: metres to the viewer's right when facing the wall
			x -= L(en.dx or 0)
			local w, h = L(en.w or 2.4), H(en.h or 2.6)
			local gy = F.ground(fp.hits[en.at][1], fp.hits[en.at][2]) or ground
			local dy = math.max(ground, gy)
			local stepsUp = (en.steps or 0) * 0.6
			local floorY = dy + stepsUp
			if en.surround then
				local sw, sh = w + L(en.surroundW or 1.2), h + H(en.surroundH or 0.9)
				b:part("DoorSurround", Vector3.new(sw, sh, 0.7), e.face * CFrame.new(x, floorY + sh / 2, -0.3),
					mat(en.surroundMaterial, Enum.Material.Limestone), hex(en.surround))
				if en.style == "arch" then
					local arch = b:part("DoorArch", Vector3.new(0.7, sw, sw), e.face * CFrame.new(x, floorY + sh, -0.3) * CFrame.Angles(0, math.pi / 2, 0),
						mat(en.surroundMaterial, Enum.Material.Limestone), hex(en.surround))
					arch.Shape = Enum.PartType.Cylinder
				end
				if en.pediment then
					for side = -1, 1, 2 do
						b:wedge("DoorPediment", Vector3.new(0.9, H(0.9), sw / 2 + 0.6),
							e.face * CFrame.new(x + side * (sw / 4 + 0.3), floorY + sh + H(0.45), -0.45) * CFrame.Angles(0, side > 0 and -math.pi / 2 or math.pi / 2, 0),
							mat(en.surroundMaterial, Enum.Material.Limestone), hex(en.surround))
					end
				end
			end
			b:part("Door", Vector3.new(w, h, 0.4), e.face * CFrame.new(x, floorY + h / 2, -0.55), en.glass and Enum.Material.Glass or Enum.Material.Wood,
				en.color and hex(en.color) or Color3.fromRGB(60, 56, 54))
			if (en.w or 2.4) >= 1.8 then
				b:part("DoorSplit", Vector3.new(0.25, h, 0.5), e.face * CFrame.new(x, floorY + h / 2, -0.7), Enum.Material.Metal, Color3.fromRGB(70, 70, 72))
			end
			if en.above then
				-- round-headed window over the door (stone-trimmed)
				local aw, ah = L(en.above.w or 1.4), H(en.above.h or 2.0)
				local ay = floorY + h + H(en.above.gap or 1.2)
				b:part("ArchWindowTrim", Vector3.new(aw + 1, ah + 0.6, 0.5), e.face * CFrame.new(x, ay + ah / 2, -0.25), Enum.Material.Limestone,
					en.surround and hex(en.surround) or Color3.fromRGB(214, 206, 190))
				b:part("ArchWindow", Vector3.new(aw, ah, 0.4), e.face * CFrame.new(x, ay + ah / 2, -0.45), Enum.Material.Glass, glassDefault)
				local head = b:part("ArchWindowHead", Vector3.new(0.4, aw, aw), e.face * CFrame.new(x, ay + ah, -0.45) * CFrame.Angles(0, math.pi / 2, 0),
					Enum.Material.Glass, glassDefault)
				head.Shape = Enum.PartType.Cylinder
			end
			if en.transom then
				b:part("Transom", Vector3.new(w, H(0.7), 0.4), e.face * CFrame.new(x, floorY + h + H(0.4), -0.55), Enum.Material.Glass, glassDefault)
			end
			for k = 1, en.steps or 0 do
				-- step k (1 = bottom) tops out at gy + k*0.6, its tread runs out from the wall
				local sd = L(0.35) * (en.steps - k + 1)
				local y0, y1 = gy - 1, dy + k * 0.6
				b:part("Step", Vector3.new(w + L(1.6), y1 - y0, sd), e.face * CFrame.new(x, (y0 + y1) / 2, -sd / 2),
					Enum.Material.Concrete, Color3.fromRGB(190, 186, 178), true)
			end
			if en.canopy then
				local d = L(en.canopy.d or 2.5)
				local cw = L(en.canopy.w or (en.w or 2.4) + 3)
				local cy = floorY + h + H(en.canopy.y or 0.6)
				b:part("Canopy", Vector3.new(cw, H(0.4), d), e.face * CFrame.new(x, cy, -d / 2), Enum.Material.SmoothPlastic,
					en.canopy.color and hex(en.canopy.color) or Color3.fromRGB(220, 218, 210), true)
				if en.canopy.posts then
					for side = -1, 1, 2 do
						b:part("CanopyPost", Vector3.new(0.6, cy - gy, 0.6), e.face * CFrame.new(x + side * (cw / 2 - 1), gy + (cy - gy) / 2, -d + 1),
							Enum.Material.Metal, en.canopy.postColor and hex(en.canopy.postColor) or Color3.fromRGB(80, 80, 84), true)
					end
				end
			end
			if en.columns then
				local cw = L(en.columns.w or 6)
				local d = L(en.columns.d or 2.5)
				local ch = H(en.columns.h or 4)
				local n = en.columns.n or 2
				local col = en.columns.color and hex(en.columns.color) or Color3.fromRGB(226, 222, 212)
				for k = 0, n - 1 do
					local cx = x - cw / 2 + cw * k / math.max(n - 1, 1)
					local c = b:part("Column", Vector3.new(ch, L(0.5), L(0.5)), e.face * CFrame.new(cx, floorY + ch / 2, -d + 1) * CFrame.Angles(0, 0, math.pi / 2),
						Enum.Material.Concrete, col, true)
					c.Shape = Enum.PartType.Cylinder
				end
				b:part("Entablature", Vector3.new(cw + 2, H(0.7), d + 0.6), e.face * CFrame.new(x, floorY + ch + H(0.35), -d / 2 + 0.3), Enum.Material.Concrete, col)
			end
		end
	end

	-- projecting feature blocks the photos show (entrance towers, bays)
	for _, bk in ipairs(P.blocks or {}) do
		local e, x = anchor(bk.at)
		if e then
			local w, d, hh = L(bk.w or 6), L(bk.d or 1.5), H(bk.h or wallH + 1)
			local c = bk.color and hex(bk.color) or wall
			local blk = b:part("FeatureBlock", Vector3.new(w, hh + 1.5, d + 1), e.face * CFrame.new(x + L(bk.dx or 0), ground + hh / 2 - 0.75, -d / 2 + 0.5),
				mat(bk.material, Enum.Material.SmoothPlastic), c, true)
			if bk.glass then
				b:part("FeatureGlass", Vector3.new(w * (bk.glass.w or 0.35), H(bk.glass.h or wallH - 2), 0.3),
					e.face * CFrame.new(x + L(bk.dx or 0) + w * (bk.glass.x or 0), ground + H(bk.glass.y or 1) + H(bk.glass.h or wallH - 2) / 2, -d - 0.1),
					Enum.Material.Glass, glassDefault)
			end
			if bk.letters then
				-- stacked letters down the face (one label per letter)
				local n = #bk.letters
				local col = {}
				for i, ch in ipairs(bk.letters) do
					col[i] = { text = ch, size = (bk.letterSize or 0.6) / n, y = (bk.letterTop or 0.25) + (i - 1) * (bk.letterSize or 0.6) / n,
						x = bk.letterX or 0.62, wScale = 0.3, font = Enum.Font.GothamBold, color = Color3.new(1, 1, 1) }
				end
				Shapes.signText(blk, Enum.NormalId.Front, col, 12)
			end
			if bk.emblem then
				local em = b:part("Emblem", Vector3.new(0.3, L(bk.emblem.d or 1.6), L(bk.emblem.d or 1.6)),
					e.face * CFrame.new(x + L(bk.dx or 0) + w * (bk.emblem.x or 0.18), ground + H(bk.emblem.y or wallH - 2), -d - 0.1) * CFrame.Angles(0, math.pi / 2, 0),
					Enum.Material.SmoothPlastic, hex(bk.emblem.color or 0xffffff))
				em.Shape = Enum.PartType.Cylinder
			end
		end
	end

	-- signs, with the text the photographs show
	for _, sg in ipairs(P.signs or {}) do
		local e, x, h = anchor(sg.at)
		if e then
			local w, hh = L(sg.w or 3), H(sg.h or 0.9)
			local bg = sg.bg and hex(sg.bg) or Color3.fromRGB(30, 40, 70)
			local lines = {}
			local yAcc = 0.06
			for _, l in ipairs(sg.lines) do
				table.insert(lines, { text = l[1], size = l[2] or 0.4, y = l.y or yAcc, font = FONTS[l.font or sg.font or "sans"] or Enum.Font.GothamBold,
					color = l.color and hex(l.color) or (sg.fg and hex(sg.fg) or Color3.new(1, 1, 1)), x = l.x, wScale = l.wScale })
				yAcc += (l[2] or 0.4) + 0.04
			end
			if sg.kind == "awning" then
				-- a sloped fabric awning over the doors, lettering on its face
				local y = ground + H(sg.y or 3.2)
				local d = L(sg.d or 1.2)
				local p = b:part("InstitutionSign", Vector3.new(w, hh, 0.3), e.face * CFrame.new(x + L(sg.dx or 0), y, -d), Enum.Material.Fabric, bg)
				b:part("AwningTop", Vector3.new(w, 0.3, d), e.face * CFrame.new(x + L(sg.dx or 0), y + hh / 2, -d / 2), Enum.Material.Fabric, bg)
				Shapes.signText(p, Enum.NormalId.Front, lines, 28)
			elseif sg.kind == "wall" or sg.kind == "banner" then
				local y = ground + H(sg.y or 3.2)
				local p = b:part("InstitutionSign", Vector3.new(w, hh, 0.3), e.face * CFrame.new(x + L(sg.dx or 0), y, -(sg.proud or 0.5)),
					sg.kind == "banner" and Enum.Material.Fabric or Enum.Material.SmoothPlastic, bg)
				if sg.clear then p.Transparency = 1 end
				Shapes.signText(p, Enum.NormalId.Front, lines, 28)
			else
				-- freestanding: on the lawn between the wall and the camera
				local hit = F.pt(h[1], h[2])
				local cam = F.pt(h[3], h[4])
				local dir = (cam - hit)
				local dist = dir.Magnitude
				dir = dist > 0 and dir / dist or e.n
				local pos = hit + dir * math.min(L(sg.out or 6), dist * 0.8) + e.right * L(sg.dx or 0)
				if sg.dist then
					-- measured along the photo ray from the camera
					pos = cam - dir * math.min(L(sg.dist), dist - 2) + e.right * L(sg.dx or 0)
				end
				local gy = ctx.terrainY(pos.X, pos.Z) or ground
				local facing = sg.faceStreet and dir or e.n
				local M = CFrame.lookAt(Vector3.new(pos.X, gy, pos.Z), Vector3.new(pos.X, gy, pos.Z) + facing)
				local lift = H(sg.lift or (sg.kind == "pylon" and 1.6 or sg.kind == "board" and 0.8 or 0))
				if sg.kind == "pylon" and sg.body then
					local body = b:part("SignBody", Vector3.new(L(sg.body.w or 1.2), lift, L(sg.body.d or 0.5)), M * CFrame.new(0, lift / 2, 0.1),
						Enum.Material.Metal, sg.post and hex(sg.post) or Color3.fromRGB(28, 28, 30), true)
					if sg.body.text then
						Shapes.signText(body, Enum.NormalId.Front, { { text = sg.body.text, size = 0.12, y = sg.body.y or 0.55, x = 0.25, wScale = 0.5,
							font = Enum.Font.GothamBold, color = Color3.new(1, 1, 1) } }, 28)
					end
				elseif sg.kind == "monument" then
					b:part("SignBase", Vector3.new(w + L(0.4), hh + lift + 1, L(0.6)), M * CFrame.new(0, (hh + lift) / 2 - 0.5, 0.15),
						mat(sg.baseMaterial, Enum.Material.Brick), sg.base and hex(sg.base) or Color3.fromRGB(140, 74, 56), true)
				else
					for side = -1, 1, 2 do
						if sg.kind == "board" or side == -1 then
							b:part("SignPost", Vector3.new(0.5, lift + hh, 0.5),
								M * CFrame.new(sg.kind == "pylon" and 0 or side * (w / 2 - 0.4), (lift + hh) / 2, 0.3), Enum.Material.Metal,
								sg.post and hex(sg.post) or Color3.fromRGB(40, 40, 42), true)
						end
					end
				end
				local p = b:part("InstitutionSign", Vector3.new(w, hh, 0.35), M * CFrame.new(0, lift + hh / 2, -0.05),
					Enum.Material.SmoothPlastic, bg, true)
				Shapes.signText(p, Enum.NormalId.Front, lines, 28)
				if sg.twoSided then
					Shapes.signText(p, Enum.NormalId.Back, lines, 28)
				end
			end
		end
	end
	return top
end

return Poly
